INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'ஆழ்ந்த கற்றல் எந்த துறையின் துணைப்பிரிவு?','இயந்திரக் கற்றல்','இயற்பியல்','இயந்திரவியல்','கணக்கியல்','இயந்திரக் கற்றல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'நியூரானின் உள்ளீடுகளை இணைக்கும் அளவுரு எது?','எடை','கோப்பு பெயர்','IP முகவரி','போர்ட்','எடை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'பின்னோக்கு பரப்புதலின் நோக்கம் என்ன?','எடைகளை பிழையின் அடிப்படையில் புதுப்பித்தல்','தரவுகளை அழித்தல்','படங்களை மட்டும் சேமித்தல்','வலையமைப்பை அமைத்தல்','எடைகளை பிழையின் அடிப்படையில் புதுப்பித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'ReLU செயல்பாடு பொதுவாக எதைச் செய்கிறது?','எதிர்மறை மதிப்புகளை பூஜ்ஜியமாக்குகிறது','அனைத்து மதிப்புகளையும் அழிக்கிறது','IP முகவரி உருவாக்குகிறது','கோப்புகளை சுருக்குகிறது','எதிர்மறை மதிப்புகளை பூஜ்ஜியமாக்குகிறது','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'இழப்பு செயல்பாடு எதை அளக்கிறது?','கணிப்பு மற்றும் உண்மை இடையிலான பிழை','CPU வேகம்','நினைவக அளவு','கோப்பு அளவு','கணிப்பு மற்றும் உண்மை இடையிலான பிழை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'Gradient Descent எதற்காக பயன்படுகிறது?','இழப்பை குறைக்க அளவுருக்களை மேம்படுத்த','படங்களை சேமிக்க','வலையமைப்பு இணைக்க','கோப்புகளை பெயரிட','இழப்பை குறைக்க அளவுருக்களை மேம்படுத்த','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'CNN எந்த தரவுக்கு மிகவும் பொதுவாக பயன்படுகிறது?','படத் தரவு','கடவுச்சொற்கள்','IP முகவரிகள்','கோப்பு பெயர்கள்','படத் தரவு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'RNN எந்த வகை தரவுக்கு பயனுள்ளது?','வரிசைத் தரவு','நிலையான படங்கள் மட்டும்','வட்டு தொகுதிகள்','MAC முகவரிகள்','வரிசைத் தரவு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'LSTM எந்த பிரச்சினையை சமாளிக்க உதவுகிறது?','நீண்டகால சார்புகளை கையாளுதல்','IP முகவரி மாற்றம்','கோப்பு அழித்தல்','CPU வெப்பம்','நீண்டகால சார்புகளை கையாளுதல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'Dropout ஏன் பயன்படுத்தப்படுகிறது?','அதிகப்படியான பொருத்தத்தை குறைக்க','தரவு சேமிப்பை அதிகரிக்க','வலையமைப்பை துண்டிக்க','படங்களை பெரிதாக்க','அதிகப்படியான பொருத்தத்தை குறைக்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'GRU தொடர்பாக, ஆழ்ந்த கற்றல் எந்த துறையின் துணைப்பிரிவு? (உதாரணம் 11)','இயந்திரக் கற்றல்','இயற்பியல்','இயந்திரவியல்','கணக்கியல்','இயந்திரக் கற்றல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'ஆட்டோஎன்கோடர் தொடர்பாக, நியூரானின் உள்ளீடுகளை இணைக்கும் அளவுரு எது? (உதாரணம் 12)','எடை','கோப்பு பெயர்','IP முகவரி','போர்ட்','எடை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'டிரான்ஸ்ஃபார்மர் தொடர்பாக, பின்னோக்கு பரப்புதலின் நோக்கம் என்ன? (உதாரணம் 13)','எடைகளை பிழையின் அடிப்படையில் புதுப்பித்தல்','தரவுகளை அழித்தல்','படங்களை மட்டும் சேமித்தல்','வலையமைப்பை அமைத்தல்','எடைகளை பிழையின் அடிப்படையில் புதுப்பித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'கவனிப்பு முறை தொடர்பாக, reLU செயல்பாடு பொதுவாக எதைச் செய்கிறது? (உதாரணம் 14)','எதிர்மறை மதிப்புகளை பூஜ்ஜியமாக்குகிறது','அனைத்து மதிப்புகளையும் அழிக்கிறது','IP முகவரி உருவாக்குகிறது','கோப்புகளை சுருக்குகிறது','எதிர்மறை மதிப்புகளை பூஜ்ஜியமாக்குகிறது','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'மாடல் மதிப்பீடு தொடர்பாக, இழப்பு செயல்பாடு எதை அளக்கிறது? (உதாரணம் 15)','கணிப்பு மற்றும் உண்மை இடையிலான பிழை','CPU வேகம்','நினைவக அளவு','கோப்பு அளவு','கணிப்பு மற்றும் உண்மை இடையிலான பிழை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'ஆழ்ந்த கற்றல் அடிப்படைகள் தொடர்பாக, gradient Descent எதற்காக பயன்படுகிறது? (உதாரணம் 16)','இழப்பை குறைக்க அளவுருக்களை மேம்படுத்த','படங்களை சேமிக்க','வலையமைப்பு இணைக்க','கோப்புகளை பெயரிட','இழப்பை குறைக்க அளவுருக்களை மேம்படுத்த','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'நியூரல் நெட்வொர்க் தொடர்பாக, cNN எந்த தரவுக்கு மிகவும் பொதுவாக பயன்படுகிறது? (உதாரணம் 17)','படத் தரவு','கடவுச்சொற்கள்','IP முகவரிகள்','கோப்பு பெயர்கள்','படத் தரவு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'பின்னோக்கு பரப்புதல் தொடர்பாக, rNN எந்த வகை தரவுக்கு பயனுள்ளது? (உதாரணம் 18)','வரிசைத் தரவு','நிலையான படங்கள் மட்டும்','வட்டு தொகுதிகள்','MAC முகவரிகள்','வரிசைத் தரவு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'செயல்படுத்தும் செயல்பாடுகள் தொடர்பாக, lSTM எந்த பிரச்சினையை சமாளிக்க உதவுகிறது? (உதாரணம் 19)','நீண்டகால சார்புகளை கையாளுதல்','IP முகவரி மாற்றம்','கோப்பு அழித்தல்','CPU வெப்பம்','நீண்டகால சார்புகளை கையாளுதல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'இழப்பு செயல்பாடுகள் தொடர்பாக, dropout ஏன் பயன்படுத்தப்படுகிறது? (உதாரணம் 20)','அதிகப்படியான பொருத்தத்தை குறைக்க','தரவு சேமிப்பை அதிகரிக்க','வலையமைப்பை துண்டிக்க','படங்களை பெரிதாக்க','அதிகப்படியான பொருத்தத்தை குறைக்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'உகப்பாக்கிகள் தொடர்பாக, ஆழ்ந்த கற்றல் எந்த துறையின் துணைப்பிரிவு? (உதாரணம் 21)','இயந்திரக் கற்றல்','இயற்பியல்','இயந்திரவியல்','கணக்கியல்','இயந்திரக் கற்றல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'கட்டுப்படுத்தல் தொடர்பாக, நியூரானின் உள்ளீடுகளை இணைக்கும் அளவுரு எது? (உதாரணம் 22)','எடை','கோப்பு பெயர்','IP முகவரி','போர்ட்','எடை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'CNN தொடர்பாக, பின்னோக்கு பரப்புதலின் நோக்கம் என்ன? (உதாரணம் 23)','எடைகளை பிழையின் அடிப்படையில் புதுப்பித்தல்','தரவுகளை அழித்தல்','படங்களை மட்டும் சேமித்தல்','வலையமைப்பை அமைத்தல்','எடைகளை பிழையின் அடிப்படையில் புதுப்பித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'RNN தொடர்பாக, reLU செயல்பாடு பொதுவாக எதைச் செய்கிறது? (உதாரணம் 24)','எதிர்மறை மதிப்புகளை பூஜ்ஜியமாக்குகிறது','அனைத்து மதிப்புகளையும் அழிக்கிறது','IP முகவரி உருவாக்குகிறது','கோப்புகளை சுருக்குகிறது','எதிர்மறை மதிப்புகளை பூஜ்ஜியமாக்குகிறது','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'LSTM தொடர்பாக, இழப்பு செயல்பாடு எதை அளக்கிறது? (உதாரணம் 25)','கணிப்பு மற்றும் உண்மை இடையிலான பிழை','CPU வேகம்','நினைவக அளவு','கோப்பு அளவு','கணிப்பு மற்றும் உண்மை இடையிலான பிழை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'GRU தொடர்பாக, gradient Descent எதற்காக பயன்படுகிறது? (உதாரணம் 26)','இழப்பை குறைக்க அளவுருக்களை மேம்படுத்த','படங்களை சேமிக்க','வலையமைப்பு இணைக்க','கோப்புகளை பெயரிட','இழப்பை குறைக்க அளவுருக்களை மேம்படுத்த','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'ஆட்டோஎன்கோடர் தொடர்பாக, cNN எந்த தரவுக்கு மிகவும் பொதுவாக பயன்படுகிறது? (உதாரணம் 27)','படத் தரவு','கடவுச்சொற்கள்','IP முகவரிகள்','கோப்பு பெயர்கள்','படத் தரவு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'டிரான்ஸ்ஃபார்மர் தொடர்பாக, rNN எந்த வகை தரவுக்கு பயனுள்ளது? (உதாரணம் 28)','வரிசைத் தரவு','நிலையான படங்கள் மட்டும்','வட்டு தொகுதிகள்','MAC முகவரிகள்','வரிசைத் தரவு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'கவனிப்பு முறை தொடர்பாக, lSTM எந்த பிரச்சினையை சமாளிக்க உதவுகிறது? (உதாரணம் 29)','நீண்டகால சார்புகளை கையாளுதல்','IP முகவரி மாற்றம்','கோப்பு அழித்தல்','CPU வெப்பம்','நீண்டகால சார்புகளை கையாளுதல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'மாடல் மதிப்பீடு தொடர்பாக, dropout ஏன் பயன்படுத்தப்படுகிறது? (உதாரணம் 30)','அதிகப்படியான பொருத்தத்தை குறைக்க','தரவு சேமிப்பை அதிகரிக்க','வலையமைப்பை துண்டிக்க','படங்களை பெரிதாக்க','அதிகப்படியான பொருத்தத்தை குறைக்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'ஆழ்ந்த கற்றல் அடிப்படைகள் தொடர்பாக, ஆழ்ந்த கற்றல் எந்த துறையின் துணைப்பிரிவு? (உதாரணம் 31)','இயந்திரக் கற்றல்','இயற்பியல்','இயந்திரவியல்','கணக்கியல்','இயந்திரக் கற்றல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'நியூரல் நெட்வொர்க் தொடர்பாக, நியூரானின் உள்ளீடுகளை இணைக்கும் அளவுரு எது? (உதாரணம் 32)','எடை','கோப்பு பெயர்','IP முகவரி','போர்ட்','எடை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'பின்னோக்கு பரப்புதல் தொடர்பாக, பின்னோக்கு பரப்புதலின் நோக்கம் என்ன? (உதாரணம் 33)','எடைகளை பிழையின் அடிப்படையில் புதுப்பித்தல்','தரவுகளை அழித்தல்','படங்களை மட்டும் சேமித்தல்','வலையமைப்பை அமைத்தல்','எடைகளை பிழையின் அடிப்படையில் புதுப்பித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'செயல்படுத்தும் செயல்பாடுகள் தொடர்பாக, reLU செயல்பாடு பொதுவாக எதைச் செய்கிறது? (உதாரணம் 34)','எதிர்மறை மதிப்புகளை பூஜ்ஜியமாக்குகிறது','அனைத்து மதிப்புகளையும் அழிக்கிறது','IP முகவரி உருவாக்குகிறது','கோப்புகளை சுருக்குகிறது','எதிர்மறை மதிப்புகளை பூஜ்ஜியமாக்குகிறது','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'இழப்பு செயல்பாடுகள் தொடர்பாக, இழப்பு செயல்பாடு எதை அளக்கிறது? (உதாரணம் 35)','கணிப்பு மற்றும் உண்மை இடையிலான பிழை','CPU வேகம்','நினைவக அளவு','கோப்பு அளவு','கணிப்பு மற்றும் உண்மை இடையிலான பிழை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
