INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'RNN தொடர்பாக, lSTM எந்த பிரச்சினையை சமாளிக்க உதவுகிறது? (உதாரணம் 39)','நீண்டகால சார்புகளை கையாளுதல்','IP முகவரி மாற்றம்','கோப்பு அழித்தல்','CPU வெப்பம்','நீண்டகால சார்புகளை கையாளுதல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Single Choice','Medium',1,'LSTM தொடர்பாக, dropout ஏன் பயன்படுத்தப்படுகிறது? (உதாரணம் 40)','அதிகப்படியான பொருத்தத்தை குறைக்க','தரவு சேமிப்பை அதிகரிக்க','வலையமைப்பை துண்டிக்க','படங்களை பெரிதாக்க','அதிகப்படியான பொருத்தத்தை குறைக்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Multiple Choice','Hard',2,'ஆழ்ந்த நியூரல் நெட்வொர்க்கின் கூறுகள் எவை?','உள்ளீட்டு அடுக்கு','மறை அடுக்குகள்','வெளியீட்டு அடுக்கு','எடைகள்','உள்ளீட்டு அடுக்கு; மறை அடுக்குகள்; வெளியீட்டு அடுக்கு; எடைகள்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
