INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'ஆழ்ந்த கற்றல் என்றால் என்ன?','','','','','பல அடுக்குகள் கொண்ட நியூரல் நெட்வொர்க்குகளை பயன்படுத்தி தரவிலிருந்து சிக்கலான பிரதிநிதித்துவங்களை கற்றுக்கொள்ளும் இயந்திரக் கற்றல் அணுகுமுறை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'பின்னோக்கு பரப்புதல் என்றால் என்ன?','','','','','இழப்பு செயல்பாட்டின் பிழையை பின்புறமாக பரப்பி எடைகளுக்கான சாய்வுகளை கணக்கிட்டு அவற்றை புதுப்பிக்கும் முறை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'CNN என்றால் என்ன?','','','','','படங்கள் போன்ற கட்டமைக்கப்பட்ட இடவியல் தரவிலிருந்து அம்சங்களை கண்டறிய பயன்படும் நியூரல் நெட்வொர்க்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'Dropout என்றால் என்ன?','','','','','பயிற்சியின் போது சில நியூரான்களை தற்காலிகமாக செயலிழக்கச் செய்து அதிகப்படியான பொருத்தத்தை குறைக்கும் நுட்பம்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'LSTM என்றால் என்ன?','','','','','நீண்டகால சார்புகளை நினைவில் வைத்துக்கொள்ளும் வாயில் அமைப்பைக் கொண்ட மீள்முறை நியூரல் நெட்வொர்க்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'ஆழ்ந்த கற்றல் என்றால் என்ன? (விரிவாக்கக் கேள்வி 6)','','','','','பல அடுக்குகள் கொண்ட நியூரல் நெட்வொர்க்குகளை பயன்படுத்தி தரவிலிருந்து சிக்கலான பிரதிநிதித்துவங்களை கற்றுக்கொள்ளும் இயந்திரக் கற்றல் அணுகுமுறை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'பின்னோக்கு பரப்புதல் என்றால் என்ன? (விரிவாக்கக் கேள்வி 7)','','','','','இழப்பு செயல்பாட்டின் பிழையை பின்புறமாக பரப்பி எடைகளுக்கான சாய்வுகளை கணக்கிட்டு அவற்றை புதுப்பிக்கும் முறை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
