INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'LSTM என்றால் என்ன? (விரிவாக்கக் கேள்வி 25)','','','','','நீண்டகால சார்புகளை நினைவில் வைத்துக்கொள்ளும் வாயில் அமைப்பைக் கொண்ட மீள்முறை நியூரல் நெட்வொர்க்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'ஆழ்ந்த கற்றல் என்றால் என்ன? (விரிவாக்கக் கேள்வி 26)','','','','','பல அடுக்குகள் கொண்ட நியூரல் நெட்வொர்க்குகளை பயன்படுத்தி தரவிலிருந்து சிக்கலான பிரதிநிதித்துவங்களை கற்றுக்கொள்ளும் இயந்திரக் கற்றல் அணுகுமுறை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'பின்னோக்கு பரப்புதல் என்றால் என்ன? (விரிவாக்கக் கேள்வி 27)','','','','','இழப்பு செயல்பாட்டின் பிழையை பின்புறமாக பரப்பி எடைகளுக்கான சாய்வுகளை கணக்கிட்டு அவற்றை புதுப்பிக்கும் முறை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'CNN என்றால் என்ன? (விரிவாக்கக் கேள்வி 28)','','','','','படங்கள் போன்ற கட்டமைக்கப்பட்ட இடவியல் தரவிலிருந்து அம்சங்களை கண்டறிய பயன்படும் நியூரல் நெட்வொர்க்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'Dropout என்றால் என்ன? (விரிவாக்கக் கேள்வி 29)','','','','','பயிற்சியின் போது சில நியூரான்களை தற்காலிகமாக செயலிழக்கச் செய்து அதிகப்படியான பொருத்தத்தை குறைக்கும் நுட்பம்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Short Answer','Medium',2,'LSTM என்றால் என்ன? (விரிவாக்கக் கேள்வி 30)','','','','','நீண்டகால சார்புகளை நினைவில் வைத்துக்கொள்ளும் வாயில் அமைப்பைக் கொண்ட மீள்முறை நியூரல் நெட்வொர்க்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Long Answer','Hard',5,'ஆழ்ந்த நியூரல் நெட்வொர்க்கின் கட்டமைப்பை விளக்குக.','','','','','உள்ளீட்டு அடுக்கு, பல மறை அடுக்குகள் மற்றும் வெளியீட்டு அடுக்கு ஆகியவை நெட்வொர்க்கின் முக்கிய பகுதிகள். எடைகள் மற்றும் செயல்படுத்தும் செயல்பாடுகள் மூலம் தரவு மாற்றப்படுகிறது.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Long Answer','Hard',5,'பின்னோக்கு பரப்புதல் மற்றும் Gradient Descent-ஐ விளக்குக.','','','','','முன்னோக்கு கணக்கீட்டில் கணிப்பு உருவாக்கப்படுகிறது. இழப்பு கணக்கிடப்பட்ட பிறகு பின்னோக்கு பரப்புதல் சாய்வுகளை பெறுகிறது; Gradient Descent அவற்றைப் பயன்படுத்தி எடைகளை மேம்படுத்துகிறது.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Long Answer','Hard',5,'CNN செயல்பாட்டை விளக்குக.','','','','','Convolution அடுக்குகள் உள்ளூர் அம்சங்களை கண்டறிகின்றன; Pooling பரிமாணத்தை குறைக்கிறது; பின்னர் அடுக்குகள் உயர் நிலை அம்சங்களை கற்று வகைப்பாட்டிற்கு பயன்படுத்துகின்றன.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Long Answer','Hard',5,'அதிகப்படியான பொருத்தத்தை குறைக்கும் நுட்பங்களை விளக்குக.','','','','','Dropout, Regularization, Early Stopping, Data Augmentation மற்றும் அதிகமான பயிற்சி தரவு போன்ற முறைகள் பொதுவாக அதிகப்படியான பொருத்தத்தை குறைக்க உதவுகின்றன.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Long Answer','Hard',5,'LSTM அமைப்பை விளக்குக.','','','','','LSTM-ல் உள்ளீட்டு, மறதி மற்றும் வெளியீட்டு வாயில்கள் மூலம் தகவலை நினைவில் வைத்தல் அல்லது மறத்தல் கட்டுப்படுத்தப்படுகிறது. இதனால் நீண்ட வரிசை சார்புகளை கையாள முடியும்.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_deep_learning_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM-Deep Learning','தமிழ்','Long Answer','Hard',5,'ஆழ்ந்த நியூரல் நெட்வொர்க்கின் கட்டமைப்பை விளக்குக. (பயன்பாட்டு நிலை 6)','','','','','உள்ளீட்டு அடுக்கு, பல மறை அடுக்குகள் மற்றும் வெளியீட்டு அடுக்கு ஆகியவை நெட்வொர்க்கின் முக்கிய பகுதிகள். எடைகள் மற்றும் செயல்படுத்தும் செயல்பாடுகள் மூலம் தரவு மாற்றப்படுகிறது.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
